from __future__ import annotations

import re
from typing import Any

from .qwen3_hf_generate import (
    result_text as _hf_result_text,
)
from .qwen3_constants import (
    _QWEN_SR,
)
from .qwen3_singing import (
    _GAP_BREAK_S_SINGING,
    _MAX_CUE_S_SINGING,
    _MAX_JOIN_CHARS_SINGING,
    _words_to_singing_cues,
)

_MAX_CUE_S = 6.5


_GAP_BREAK_S = 0.4


_TARGET_CUE_CHARS = 28


_ECHO_MIN_BARE = 8


_SENTENCE_SPLIT_RE = re.compile(r"(?<=[。！？!?．.｡…])")


_BARE_PUNCT_RE = re.compile(r"[。．.!！?？、,\s…·・♪\[\]]+")

# Qwen leftover shards of センチの (れんち/えんち) — reusable phonetic, not title-gated.
_CENTI_SHARD_RE = re.compile(
    r"^(?:[えエ]?[んン]ち|[レれ]ンチ|[エエ]ンチ)の?$"
)
_CENTI_SHARD_IN_RE = re.compile(r"(?:えんち|エンチ|レンチ)の?")


def _bare_cue_text(text: str) -> str:
    return _BARE_PUNCT_RE.sub("", str(text or "").strip())


def _fold_measure_ja(text: str) -> str:
    """Fold cm / センチ / leftover えんち so 175cm echoes 175センチ."""
    s = _bare_cue_text(text)
    s = _CENTI_SHARD_IN_RE.sub("センチ", s)
    s = s.replace("センチメートル", "CM")
    s = s.replace("センチ", "CM")
    s = s.replace("㎝", "CM")
    s = re.sub(r"(?i)cm", "CM", s)
    return s


def _cue_text_is_measure_shard(text: str) -> bool:
    return bool(_CENTI_SHARD_RE.fullmatch(_bare_cue_text(text)))


_ECHO_FILLER_PREFIX_RE = re.compile(
    r"^(?:えー+|えっと|あの+|まあ|うーん*|ん+|あ+|あぁ+|あっ|ええ+|はぁ*|ふ+|うっ?)"
)


def _cue_text_is_echo(new_text: str, prev_text: str) -> bool:
    """True when leftover/next cue repeats the previous phrase (身長が175cm).

    Also catches short tail leftovers that used to slip under ``_ECHO_MIN_BARE``
    (この勃起は… after つまり、この勃起は…; 硬いのが背中に… after a longer line).
    Avoids false hits where a short word merely appears inside a new turn
    (気持ちいい → 旦那とどっちが気持ちいい).
    """
    if _cue_text_is_measure_shard(new_text) and re.search(
        r"CM|センチ|身長|カップ", _fold_measure_ja(prev_text)
    ):
        return True
    # Fold measures on both sides; a=previous, b=next/leftover.
    a = _fold_measure_ja(prev_text)
    b = _fold_measure_ja(new_text)
    if not a or not b:
        return False
    if a == b:
        return True
    # Tail leftover: next replays the end of prev.
    if len(b) >= 4 and len(a) > len(b) and a.endswith(b):
        return True
    # Head re-echo: next is prev with a short filler lead.
    if len(a) >= 4 and len(b) > len(a) and b.endswith(a):
        prefix = b[: len(b) - len(a)]
        if _ECHO_FILLER_PREFIX_RE.match(prefix) or len(a) / len(b) >= 0.62:
            return True
    shorter, longer = (a, b) if len(a) <= len(b) else (b, a)
    if len(shorter) < _ECHO_MIN_BARE:
        return False
    if shorter not in longer:
        return False
    # High-ratio containment only at edges (legacy measure / intro echoes).
    if len(shorter) / len(longer) < 0.55 and len(shorter) < 12:
        return False
    return longer.endswith(shorter) or longer.startswith(shorter)


def _split_sentences(text: str) -> list[str]:
    raw = str(text or "").strip()
    if not raw:
        return []
    parts = [p.strip() for p in _SENTENCE_SPLIT_RE.split(raw) if p and p.strip()]
    if len(parts) <= 1 and len(raw) > _TARGET_CUE_CHARS * 2:
        chunk = _TARGET_CUE_CHARS
        parts = [raw[i : i + chunk].strip() for i in range(0, len(raw), chunk)]
        parts = [p for p in parts if p]
    return parts or [raw]


def _distribute_text_cues(
    text: str,
    *,
    start: float,
    end: float,
    speech_spans: list[tuple[float, float]] | None = None,
) -> list[dict[str, Any]]:
    """Paint ASR text onto speech-active spans (fallback: full VAD window)."""
    try:
        from .whisper_fw import (
            ensure_readable_cue_timings,
            paint_text_onto_speech_spans,
            split_frame_text_to_cues,
        )

        if speech_spans:
            cues = paint_text_onto_speech_spans(
                text,
                island_start=float(start),
                island_end=float(end),
                speech_spans=speech_spans,
                preserve_acoustic_ends=True,
            )
            if cues:
                return cues
        cues = split_frame_text_to_cues(text, float(start), float(end))
        if cues:
            return ensure_readable_cue_timings(
                cues,
                media_end_s=float(end),
                stretch_to_reading_rate=False,
            )
    except Exception:
        pass
    parts = _split_sentences(text)
    if not parts:
        return []
    span = max(0.35, float(end) - float(start))
    weights = [max(1, len(p)) for p in parts]
    total_w = float(sum(weights))
    cues: list[dict[str, Any]] = []
    cursor = float(start)
    for i, (part, w) in enumerate(zip(parts, weights)):
        frac = w / total_w
        dur = span * frac
        if i == len(parts) - 1:
            cue_end = float(end)
        else:
            cue_end = min(float(end), cursor + max(0.35, dur))
        cue_end = max(cue_end, cursor + 0.25)
        cues.append(
            {
                "start": cursor,
                "end": min(cue_end, cursor + _MAX_CUE_S * 2),
                "text": part,
            }
        )
        cursor = cue_end
    try:
        from .whisper_fw import ensure_readable_cue_timings

        return ensure_readable_cue_timings(
            cues,
            media_end_s=float(end),
            stretch_to_reading_rate=False,
        )
    except Exception:
        return cues


def _clamp_cues_to_island(
    cues: list[dict[str, Any]],
    *,
    island_lo: float,
    island_hi: float,
) -> list[dict[str, Any]]:
    """Keep acoustic cue bounds; only clamp into the VAD island (no rescale)."""
    lo = float(island_lo)
    hi = float(island_hi)
    if hi <= lo:
        hi = lo + 0.35
    out: list[dict[str, Any]] = []
    for cue in cues or []:
        cs = max(lo, min(float(cue.get("start") or lo), hi))
        ce = max(cs + 0.25, min(float(cue.get("end") or cs), hi))
        item = {**cue, "start": cs, "end": ce}
        out.append(item)
    return out


def _speech_spans_from_frame_pcm(
    item: Any,
    *,
    island_start: float,
) -> list[tuple[float, float]] | None:
    """Derive absolute speech subspans from an island PCM tuple ``(clip, sr)``."""
    if not item or not isinstance(item, (tuple, list)) or len(item) < 2:
        return None
    try:
        from .whisper_fw import pcm_speech_intervals
        import numpy as np

        spans = pcm_speech_intervals(
            item[0],
            int(item[1] or _QWEN_SR),
            offset_s=float(island_start),
            # Keep real turn pauses as separate paint spans. Soft tails are
            # handled by onset/offset hysteresis + end_pad inside pcm_speech_intervals
            # (not by widening merge_gap, which drifts whole cues).
            # frame_ms=10: Transub Pro energy hop parity.
            frame_ms=10.0,
            merge_gap_s=0.20,
            min_speech_s=0.10,
            pad_s=0.03,
            end_pad_s=0.12,
        )
        if not spans:
            return None
        # Drop weak residual blips (breath / room tone) that are much quieter
        # than the loudest span — extras break 1:1 sentence↔span paint and
        # starve real lines of their measured end times.
        clip = np.asarray(item[0], dtype=np.float32).reshape(-1)
        sr = max(1000, int(item[1] or _QWEN_SR))
        energies: list[float] = []
        for a, b in spans:
            i0 = max(0, int(round((float(a) - float(island_start)) * sr)))
            i1 = min(clip.size, int(round((float(b) - float(island_start)) * sr)))
            if i1 <= i0:
                energies.append(0.0)
                continue
            energies.append(float(np.sqrt(np.mean(np.square(clip[i0:i1])) + 1e-12)))
        peak_e = max(energies) if energies else 0.0
        if peak_e <= 1e-6:
            return spans
        # Soft-AV mix (no Demucs): quieter turns inside a FireRed island are often
        # 0.12–0.20× the loudest span. Filtering them at 0.22× drops the middle
        # phrase (e.g. DLDSS-559 「昨日テレビで」) and paints it onto the next
        # loud span → TV_LATE / MADE_LATE. Keep any span ≥0.35s regardless.
        kept = [
            sp
            for sp, en in zip(spans, energies)
            if (sp[1] - sp[0]) >= 0.35
            or (en >= peak_e * 0.12 and (sp[1] - sp[0]) >= 0.12)
        ]
        return kept or spans
    except Exception:
        return None


def _ts_items_to_cues(
    time_stamps: Any,
    *,
    offset_s: float = 0.0,
    gap_break_s: float | None = None,
    max_cue_s: float | None = None,
    max_join_chars: int | None = None,
) -> list[dict[str, Any]]:
    """Convert Qwen ForcedAligner timestamp list into subtitle cues."""
    if not time_stamps:
        return []
    gap_lim = float(_GAP_BREAK_S if gap_break_s is None else gap_break_s)
    cue_cap = float(_MAX_CUE_S if max_cue_s is None else max_cue_s)
    join_cap = int(28 if max_join_chars is None else max(6, max_join_chars))
    items: list[tuple[float, float, str]] = []
    for ts in time_stamps:
        text = str(getattr(ts, "text", None) or getattr(ts, "word", None) or "").strip()
        if not text:
            continue
        start = float(getattr(ts, "start_time", None) or getattr(ts, "start", 0) or 0)
        end = float(getattr(ts, "end_time", None) or getattr(ts, "end", start) or start)
        items.append((start + offset_s, max(end, start) + offset_s, text))
    if not items:
        return []

    cues: list[dict[str, Any]] = []
    buf: list[str] = []
    buf_start = items[0][0]
    prev_end = items[0][1]
    for start, end, text in items:
        gap = start - prev_end
        flush = False
        if buf and gap >= gap_lim:
            flush = True
        joined = "".join(buf)
        if buf and len(joined) >= join_cap:
            flush = True
        if buf and joined and joined[-1] in "。！？!?．.｡":
            flush = True
        if flush:
            cues.append(
                {
                    "start": buf_start,
                    "end": min(max(prev_end, buf_start + 0.25), buf_start + cue_cap),
                    "text": joined.strip(),
                }
            )
            buf = []
            buf_start = start
        buf.append(text)
        prev_end = max(prev_end, end)
    if buf:
        cues.append(
            {
                "start": buf_start,
                "end": min(max(prev_end, buf_start + 0.25), buf_start + cue_cap),
                "text": "".join(buf).strip(),
            }
        )
    return [c for c in cues if str(c.get("text") or "").strip()]


def _result_text(result: Any) -> str:
    return _hf_result_text(result)


def _stamps_to_words(time_stamps: Any, *, offset_s: float = 0.0) -> list[dict[str, Any]]:
    """ForcedAligner items → ``{word,start,end}`` (absolute seconds)."""
    words: list[dict[str, Any]] = []
    if not time_stamps:
        return words
    for ts in time_stamps:
        text = str(getattr(ts, "text", None) or getattr(ts, "word", None) or "").strip()
        if not text:
            continue
        start = float(getattr(ts, "start_time", None) or getattr(ts, "start", 0) or 0)
        end = float(getattr(ts, "end_time", None) or getattr(ts, "end", start) or start)
        words.append(
            {
                "word": text,
                "start": start + float(offset_s),
                "end": max(end, start) + float(offset_s),
            }
        )
    return words


def _attach_words_to_cues(
    cues: list[dict[str, Any]],
    words: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Attach word timestamps to cues by mid-point overlap."""
    if not cues or not words:
        return cues
    buckets: list[list[dict[str, Any]]] = [[] for _ in cues]
    for w in words:
        mid = (float(w["start"]) + float(w["end"])) * 0.5
        placed = False
        for i, cue in enumerate(cues):
            if float(cue["start"]) - 0.05 <= mid <= float(cue["end"]) + 0.05:
                buckets[i].append(w)
                placed = True
                break
        if not placed and cues:
            # Clamp onto nearest cue rather than dropping word metadata.
            best = min(
                range(len(cues)),
                key=lambda i: abs(
                    mid - (float(cues[i]["start"]) + float(cues[i]["end"])) * 0.5
                ),
            )
            buckets[best].append(w)
    for cue, bucket in zip(cues, buckets):
        if bucket:
            cue["words"] = bucket
    return cues


def _rescale_cues_to_span(
    cues: list[dict[str, Any]],
    *,
    start: float,
    end: float,
) -> list[dict[str, Any]]:
    """Stretch cue group times so they fill ``[start, end]`` (keep relative gaps)."""
    if not cues:
        return []
    t0 = min(float(c.get("start") or 0) for c in cues)
    t1 = max(float(c.get("end") or 0) for c in cues)
    src = max(0.05, t1 - t0)
    dst = max(0.35, float(end) - float(start))
    out: list[dict[str, Any]] = []
    for i, cue in enumerate(cues):
        cs = float(cue.get("start") or t0)
        ce = float(cue.get("end") or cs)
        ns = float(start) + (cs - t0) / src * dst
        if i == len(cues) - 1:
            ne = float(end)
        else:
            ne = float(start) + (ce - t0) / src * dst
        item = {
            **cue,
            "start": ns,
            "end": max(ns + 0.25, ne),
        }
        out.append(item)
    return out


def _result_to_cues_aligned(
    result: Any,
    *,
    offset_s: float,
    span_s: float,
    speech_spans: list[tuple[float, float]] | None = None,
    singing: bool = False,
) -> list[dict[str, Any]]:
    """Build subtitle cues for an island/window.

    When ForcedAligner finds usable acoustic groups, keep those absolute
    start/end times (clamped to the island). Do **not** rescale onto the full
    VAD span — that was the main early+late drift for the word-align preset.
    Soft-AV recall still comes from island ASR text; uncovered soft speech
    falls back to speech-span / char-proportional paint.
    """
    text = _result_text(result)
    if not text:
        return []
    # Use the full island end (Pro island worker). The old 0.95 shrink pulled
    # soft-AV phrase tails early before ten_pcm / hold polish could recover.
    end = float(offset_s) + max(0.35, float(span_s))
    stamps = getattr(result, "time_stamps", None)
    words = _stamps_to_words(stamps, offset_s=offset_s) if stamps else []

    if stamps:
        if singing and words:
            stamp_cues = _words_to_singing_cues(words, transcript=text)
        else:
            stamp_cues = _ts_items_to_cues(
                stamps,
                offset_s=offset_s,
                gap_break_s=_GAP_BREAK_S_SINGING if singing else None,
                max_cue_s=_MAX_CUE_S_SINGING if singing else None,
                max_join_chars=_MAX_JOIN_CHARS_SINGING if singing else None,
            )
        if len(stamp_cues) >= 1:
            stamp_text = "".join(str(c.get("text") or "") for c in stamp_cues)
            # Keep acoustic bounds when aligner retained most of the ASR text.
            if len(stamp_text.strip()) >= max(4, int(len(text) * 0.7)):
                cues = _clamp_cues_to_island(
                    stamp_cues,
                    island_lo=float(offset_s),
                    island_hi=end,
                )
                if words and not singing:
                    _attach_words_to_cues(cues, words)
                # Spoken-rate ensure_readable rewrites ForcedAligner acoustic
                # bounds into CPS estimates (test + soft-AV drift). Keep stamps;
                # only split mega-cues / drop junk flashes / clamp overlaps.
                if not singing:
                    try:
                        from .whisper_fw import ensure_readable_cue_timings

                        cues = ensure_readable_cue_timings(
                            cues,
                            media_end_s=end,
                            stretch_to_reading_rate=False,
                        )
                        if words:
                            _attach_words_to_cues(cues, words)
                    except Exception:
                        pass
                return cues

    cues = _distribute_text_cues(
        text,
        start=float(offset_s),
        end=end,
        speech_spans=speech_spans,
    )
    if words and cues:
        _attach_words_to_cues(cues, words)
    return cues


def _dedupe_echo_cues(
    all_cues: list[dict[str, Any]],
    *,
    max_gap_s: float = 4.0,
) -> list[dict[str, Any]]:
    """Drop adjacent leftover echoes; keep the longer phrase."""
    ordered = sorted(
        (c for c in (all_cues or []) if str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0.0), float(c.get("end") or 0.0)),
    )
    cleaned: list[dict[str, Any]] = []
    gap_lim = max(0.0, float(max_gap_s))
    for cue in ordered:
        item = dict(cue)
        if cleaned:
            prev = cleaned[-1]
            gap = float(item.get("start") or 0.0) - float(prev.get("end") or 0.0)
            if gap <= gap_lim and _cue_text_is_echo(
                str(item.get("text") or ""),
                str(prev.get("text") or ""),
            ):
                if len(_bare_cue_text(str(item.get("text") or ""))) > len(
                    _bare_cue_text(str(prev.get("text") or ""))
                ):
                    cleaned[-1] = item
                continue
        cleaned.append(item)
    return cleaned


def _merge_clause_fragment_cues(
    all_cues: list[dict[str, Any]],
    *,
    max_gap_s: float = 1.05,
) -> list[dict[str, Any]]:
    """Join hanging の/が/で tails onto the next cue (センチの + Fカップです)."""
    ordered = sorted(
        (dict(c) for c in (all_cues or []) if str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0.0), float(c.get("end") or 0.0)),
    )
    if len(ordered) < 2:
        return ordered
    out: list[dict[str, Any]] = []
    hang_re = re.compile(r"[のがでて]$")
    aux_re = re.compile(r"^(ただいて|ただきます|おります|ください)")
    turn_re = re.compile(r"^(じゃあ|でも|はい|うん|ええ|はぁ|え[?？]|あの、)")
    i = 0
    while i < len(ordered):
        cur = ordered[i]
        if i + 1 < len(ordered):
            nxt = ordered[i + 1]
            gap = float(nxt.get("start") or 0.0) - float(cur.get("end") or 0.0)
            left_raw = str(cur.get("text") or "").strip()
            right_raw = str(nxt.get("text") or "").strip()
            left = _bare_cue_text(left_raw)
            right = _bare_cue_text(right_raw)
            q_left = bool(re.search(r"[。．.！!？?]$", left_raw))
            aux_join = bool(
                0.0 <= gap <= 0.55
                and (
                    aux_re.match(right)
                    or (left.endswith("てい") and right.startswith("ただ"))
                    or (left.endswith("て") and right.startswith("って"))
                )
            )
            hang_join = (
                0.0 <= gap <= max_gap_s
                and 1 <= len(left) <= 18
                and hang_re.search(left)
                and right
                and not q_left
                and not turn_re.match(right_raw)
            )
            if aux_join or hang_join:
                joined = dict(cur)
                joined["end"] = float(nxt.get("end") or cur.get("end") or 0.0)
                joined["text"] = (
                    str(cur.get("text") or "").rstrip("…・. ")
                    + str(nxt.get("text") or "")
                )
                out.append(joined)
                i += 2
                continue
        out.append(cur)
        i += 1
    return out


_FILLER_START_RE = re.compile(r"^(えー+|えっと|あの+|まあ)")
_FILLER_CUE_RE = re.compile(r"^(えー+|えっと|あの+|まあ|うーん+)[…・.。]*$")
_PREV_COMPLETE_RE = re.compile(r"(?:です|ます|ました|ません|。|！|？|!|\?)$")
_LEAD_PARTICLE_RE = re.compile(r"^[のがでて]、?")
_FILLER_THEN_NO_RE = re.compile(
    r"(えー+|えっと|あの+|まあ)([…・.]*)の(?=センチ|カップ|[Ff]カップ)"
)


def _normalize_filler_no(text: str) -> str:
    s = str(text or "").strip()
    return _FILLER_THEN_NO_RE.sub(r"\1\2", s, count=1) if s else s


def _strip_lead_particle(text: str) -> str:
    s = _normalize_filler_no(text)
    return _LEAD_PARTICLE_RE.sub("", s, count=1).strip() or s


def _merge_leading_particle_cues(
    all_cues: list[dict[str, Any]],
    *,
    max_gap_s: float = 3.8,
) -> list[dict[str, Any]]:
    """Glue leftover tails that start mid-mora (のセンチのFカップ) onto the intro."""
    ordered = sorted(
        (dict(c) for c in (all_cues or []) if str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0.0), float(c.get("end") or 0.0)),
    )
    if len(ordered) < 2:
        return ordered
    out: list[dict[str, Any]] = []
    for cur in ordered:
        right = _bare_cue_text(str(cur.get("text") or ""))
        prev_txt = str(out[-1].get("text") or "") if out else ""
        gap = (
            float(cur.get("start") or 0.0) - float(out[-1].get("end") or 0.0)
            if out
            else 99.0
        )
        filler_tail = bool(_FILLER_THEN_NO_RE.match(str(cur.get("text") or "").strip()))
        filler_cont = bool(_FILLER_START_RE.match(right)) and not _PREV_COMPLETE_RE.search(
            prev_txt.strip()
        )
        if out and (
            _LEAD_PARTICLE_RE.match(right) or filler_tail or filler_cont
        ):
            prev = out[-1]
            gap = float(cur.get("start") or 0.0) - float(prev.get("end") or 0.0)
            if 0.0 <= gap <= max_gap_s and not re.search(
                r"[。！？!?]$", str(prev.get("text") or "").strip()
            ):
                tail = _strip_lead_particle(str(cur.get("text") or ""))
                if (
                    _FILLER_CUE_RE.match(_bare_cue_text(str(prev.get("text") or "")))
                    and len(out) >= 2
                ):
                    earlier = out[-2]
                    if (
                        float(cur.get("start") or 0.0)
                        - float(earlier.get("end") or 0.0)
                        <= max_gap_s
                    ):
                        earlier["end"] = float(cur.get("end") or earlier.get("end") or 0.0)
                        earlier["text"] = (
                            str(earlier.get("text") or "").rstrip("…・. ")
                            + str(prev.get("text") or "").strip()
                            + tail
                        )
                        out.pop()
                        continue
                prev["end"] = float(cur.get("end") or prev.get("end") or 0.0)
                prev["text"] = str(prev.get("text") or "").rstrip("…・. ") + tail
                continue
        out.append(cur)
    return out


def _dedupe_overlap_cues(all_cues: list[dict[str, Any]]) -> list[dict[str, Any]]:
    all_cues.sort(key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)))
    cleaned: list[dict[str, Any]] = []
    for cue in all_cues:
        text = str(cue.get("text") or "").strip()
        if not text:
            continue
        item = dict(cue)
        item["text"] = _normalize_filler_no(text) or text
        if cleaned and float(item["start"]) < float(cleaned[-1]["end"]) - 0.05:
            item["start"] = float(cleaned[-1]["end"])
            if float(item["end"]) <= float(item["start"]):
                item["end"] = float(item["start"]) + 0.25
        cleaned.append(item)
    return _finalize_cue_texts(
        _merge_leading_particle_cues(
            _merge_clause_fragment_cues(_dedupe_echo_cues(cleaned))
        )
    )


def _finalize_cue_texts(cues: list[dict[str, Any]]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for cue in cues:
        item = dict(cue)
        item["text"] = _normalize_filler_no(str(item.get("text") or ""))
        if str(item.get("text") or "").strip():
            out.append(item)
    return out
